136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
149	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
150	    }
151	
152	    /**
153	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
154	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
155	     * owner sign-ups.
156	     *
157	     * @param registrationDate the day to inspect, or {@code null}
158	     * @return {@code true} when more than the threshold of owners are registered on that day
159	     */
160	    private boolean isBulkSignupDay(LocalDate registrationDate) {
161	        return registrationDate != null
162	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
168	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
169	        validateRequiredFields(ownerFieldsDto);
170	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
174	        owner.setEmail(normalizeEmail(owner.getEmail()));
175	        validateRegistrationDate(owner.getRegistrationDate());
176	        if (owner.getRegistrationDate() == null) {
177	            owner.setRegistrationDate(LocalDate.now());
178	        }
179	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
180	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
181	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
182	        owner.setIdentityKey(buildIdentityKey(owner));
183	        if (!sharesHousehold) {
184	            rejectHouseholdDuplicate(owner.getHouseholdId());
185	        }
186	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
187	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
188	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
189	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
190	            throw new OwnerCityFullException(owner.getCity());
191	        }
192	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
193	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
194	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
195	        }
196	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
197	        owner.setCustomerCode(buildCustomerCode(owner));
198	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
199	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
200	        this.clinicService.saveOwner(owner);
201	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
202	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
203	            MembershipLevel.forOwner(owner));
204	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
205	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
206	        headers.setLocation(UriComponentsBuilder.newInstance()
207	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
208	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
209	    }
210	
211	    /**
212	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
213	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
214	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
215	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
216	     * after normalization is still rejected.
217	     *
218	     * @param ownerFieldsDto the submitted owner fields
219	     */
220	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
221	        List<String> missingFields = new ArrayList<>();
222	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
223	            missingFields.add("firstName");
224	        }
225	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
226	            missingFields.add("lastName");
227	        }
228	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
229	            missingFields.add("address");
230	        }
231	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
232	            missingFields.add("city");
233	        }
234	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
235	            missingFields.add("telephone");
236	        }
237	        if (!missingFields.isEmpty()) {
238	            throw new MissingOwnerFieldsException(missingFields);
239	        }
240	    }
241	
242	    /**
243	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
244	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
245	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
246	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
247	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
248	     * whose {@code errors} array lists {@code postcode}.
249	     *
250	     * @param postcode the submitted postcode, or {@code null} when none was supplied
251	     * @param city the owner's city, whose region determines the acceptable postcode range
252	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
253	     */
254	    private void validatePostcode(String postcode, String city) {
255	        if (!StringUtils.hasText(postcode)) {
256	            return;
257	        }
258	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
259	            throw new InvalidOwnerFieldsException(List.of("postcode"));
260	        }
261	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
262	            throw new InvalidOwnerFieldsException(List.of("postcode"));
263	        }
264	    }
265	
266	    /**
267	     * Validates an owner's optional registration date. Registration date is optional, so a missing
268	     * value is accepted (the create later defaults it to the server date). When a value is supplied
269	     * it may not lie in the future: a date later than the server's current date is rejected with a
270	     * 400 whose {@code errors} array lists {@code registrationDate}.
271	     *
272	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
273	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
274	     */
275	    private void validateRegistrationDate(LocalDate registrationDate) {
276	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
277	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
278	        }
279	    }
280	
281	    /**
282	     * Rejects a submitted owner that would join a household which already has a member. Because the
283	     * {@code householdId} is derived deterministically from the owner's last name and postcode, any
284	     * existing owner sharing that id is the same household, so a second such owner is reported to the
285	     * client as a 409 Conflict. A request may knowingly bypass this block by opting in with
286	     * {@code sharesHousehold}, in which case this check is not performed.
287	     *
288	     * @param householdId the derived household identifier of the owner about to be created
289	     */
290	    private void rejectHouseholdDuplicate(String householdId) {
291	        boolean duplicate = this.clinicService.findAllOwners().stream()
292	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
293	        if (duplicate) {
294	            throw new DuplicateOwnerIdentityException(householdId);
295	        }
296	    }
297	
298	    /**
299	     * Derives the owner's {@code identityKey}, formatted
300	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
301	     * and email have already been normalized. The household segment always carries the owner's
302	     * deterministic {@code householdId}, since owners with the same last name and postcode belong to
303	     * the same household automatically.
304	     *
305	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
306	     * @return the derived identity key
307	     */
308	    private String buildIdentityKey(Owner owner) {
309	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
310	        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
311	    }
312	
313	    /**
314	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner that
315	     * shares an existing owner's {@code lastName} (case-insensitively) and {@code postcode} while
316	     * having a different normalized {@code telephone}. Such an owner is still created, but is flagged
317	     * as a possible duplicate of the matching owner. This is only consulted for owners that did not
318	     * opt into a shared household: an owner that declares {@code sharesHousehold} is a known household
319	     * member, not a suspected duplicate, so it is never flagged. The comparison only applies when a
320	     * postcode was supplied, since both owners must share one; when several existing owners match, the
321	     * earliest (lowest id) is used.
322	     *
323	     * @param owner the normalized owner about to be created, with its telephone already normalized
324	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
325	     */
326	    private Integer findPossibleDuplicate(Owner owner) {
327	        if (!StringUtils.hasText(owner.getPostcode())) {
328	            return null;
329	        }
330	        return this.clinicService.findAllOwners().stream()
331	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
332	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
333	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
334	            .map(Owner::getId)
335	            .filter(id -> id != null)
336	            .min(Integer::compareTo)
337	            .orElse(null);
338	    }
339	
340	    /**
341	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
342	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
343	     * address; the accepted value is lower-cased before it is stored and returned.
344	     *
345	     * @param email the raw email value submitted by the client, or {@code null}
346	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
347	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
348	     */
349	    private String normalizeEmail(String email) {
350	        if (!StringUtils.hasText(email)) {
351	            return email;
352	        }
353	        if (!EMAIL_PATTERN.matcher(email).matches()) {
354	            throw new InvalidOwnerFieldsException(List.of("email"));
355	        }
356	        return email.toLowerCase();
357	    }
358	
359	    /**
360	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
361	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
362	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
363	     *
364	     * @param owner the normalized owner about to be created
365	     * @return the assigned customer code
366	     */
367	    private String buildCustomerCode(Owner owner) {
368	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
369	        return CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
370	    }
371	
372	    /**
373	     * Counts how many owners already exist that share the supplied first and last name, compared
374	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
375	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
376	     *
377	     * @param firstName the submitted owner's first name
378	     * @param lastName the submitted owner's last name
379	     * @return the number of existing owners with the same first and last name, ignoring case
380	     */
381	    private int countNamesakes(String firstName, String lastName) {
382	        return (int) this.clinicService.findAllOwners().stream()
383	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
384	                && lastName.equalsIgnoreCase(existing.getLastName()))
385	            .count();
386	    }
387	
388	    /**
389	     * Counts how many existing owners already belong to the supplied household, identified by its
390	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
391	     * owner is added (this count plus one).
392	     *
393	     * @param householdId the normalized household identifier of the owner being created
394	     * @return the number of existing owners already sharing that {@code householdId}
395	     */
396	    private int countHouseholdMembers(String householdId) {
397	        return (int) this.clinicService.findAllOwners().stream()
398	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
399	            .count();
400	    }
401	
402	    /**
403	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
404	     * enforce the per-city capacity limit when a new owner is created.
405	     *
406	     * @param city the submitted owner's city
407	     * @return the number of existing owners in that city, ignoring case
408	     */
409	    private long countOwnersInCity(String city) {
410	        return this.clinicService.findAllOwners().stream()
411	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
412	            .count();
413	    }
414	
415	    /**
416	     * Counts how many owners have already been created on the supplied registration date. Used to
417	     * enforce the per-day capacity limit when a new owner is created.
418	     *
419	     * @param registrationDate the registration date of the owner being created
420	     * @return the number of existing owners already registered on that date
421	     */
422	    /**
423	     * Rolls a registration date forward to a business day. A registration date must fall on a
424	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
425	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
426	     * from the registration date (such as the membership number's year segment) and the daily
427	     * create-limit therefore use the adjusted date.
428	     *
429	     * @param date the effective registration date, whether supplied or defaulted to the server date
430	     * @return the same date when it is a weekday, otherwise the next Monday
431	     */
432	    private LocalDate toBusinessDay(LocalDate date) {
433	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
434	            date = date.plusDays(1);
435	        }
436	        return date;
437	    }
438	
439	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
440	        return this.clinicService.findAllOwners().stream()
441	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
442	            .count();
443	    }
444	
445	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
446	    @Override
447	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
448	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
449	        if (currentOwner == null) {
450	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
451	        }
452	        currentOwner.setAddress(ownerFieldsDto.getAddress());
453	        currentOwner.setCity(ownerFieldsDto.getCity());
454	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
455	        currentOwner.setLastName(ownerFieldsDto.getLastName());
456	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
457	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
458	        this.clinicService.saveOwner(currentOwner);
459	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
460	    }
461	
462	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
463	    @Transactional
464	    @Override
465	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
466	        Owner owner = this.clinicService.findOwnerById(ownerId);
467	        if (owner == null) {
468	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
469	        }
470	        this.clinicService.deleteOwner(owner);
471	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
472	    }
473	
474	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
475	    @Override
476	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
477	        Owner owner = this.clinicService.findOwnerById(ownerId);
478	        if (owner == null) {
479	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
480	        }
481	        HttpHeaders headers = new HttpHeaders();
482	        Pet pet = petMapper.toPet(petFieldsDto);
483	        owner.setId(ownerId);
484	        pet.setOwner(owner);
485	        pet.getType().setName(null);
486	        this.clinicService.savePet(pet);
487	        PetDto petDto = petMapper.toPetDto(pet);
488	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
489	            .buildAndExpand(pet.getId()).toUri());
490	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
491	    }
492	
493	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
494	    @Override
495	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
496	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
497	        if (currentOwner != null) {
498	            Pet currentPet = this.clinicService.findPetById(petId);
499	            if (currentPet != null) {
500	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
501	                currentPet.setName(petFieldsDto.getName());
502	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
503	                this.clinicService.savePet(currentPet);
504	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
505	            }
506	        }
507	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
508	    }
509	
510	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
511	    @Override
512	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
513	        HttpHeaders headers = new HttpHeaders();
514	        Visit visit = visitMapper.toVisit(visitFieldsDto);
515	        Pet pet = new Pet();
516	        pet.setId(petId);
517	        visit.setPet(pet);
518	        this.clinicService.saveVisit(visit);
519	        VisitDto visitDto = visitMapper.toVisitDto(visit);
520	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
521	            .buildAndExpand(visit.getId()).toUri());
522	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
523	    }
524	
525	
526	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
527	    @Override
528	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
529	        Owner owner = this.clinicService.findOwnerById(ownerId);
530	        if (owner != null) {
531	            Pet pet = owner.getPet(petId);
532	            if (pet != null) {
533	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
534	            }
535	        }
536	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
537	    }
538	}
